The equation that determines the unknown is always $\int_{a}^{b} f(x)\,dx = 1$, taken over the whole domain.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.05cm, y=1cm]
\fill[gray!35, domain=0.6:4.2, variable=\x] (0.6,0) -- plot ({\x},{0.15*\x*\x}) -- (4.2,0) -- cycle;
\draw[->] (-0.4,0) -- (5.4,0) node[right] {$x$};
\draw[->] (0,-0.5) -- (0,3.0) node[above] {$f(x)$};
\draw[thick] (-0.3,0) -- (0.6,0);
\draw[thick, domain=0.6:4.2, smooth, samples=100, variable=\x] plot ({\x},{0.15*\x*\x});
\draw (4.2,0) -- (4.2,2.646);
\draw[thick] (4.2,0) -- (5.2,0);
\node[below] at (0.6,0) {$a$};
\node[below] at (4.2,0) {$b$};
\node at (3.1,0.5) {Area $= 1$};
\end{tikzpicture}
[/tikz]

foundation.question_text:
The function $f(x) = ax^{2}$ on $[0,2]$, and $0$ elsewhere, is a probability density function. Find $a$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.8cm, y=1.2cm]
\fill[gray!35, domain=0:2, variable=\x] (0,0) -- plot ({\x},{0.6*\x*\x}) -- (2,0) -- cycle;
\draw[->] (-0.4,0) -- (3.0,0) node[right] {$x$};
\draw[->] (0,-0.4) -- (0,3.1) node[above] {$f(x)$};
\draw[thick] (-0.3,0) -- (0,0);
\draw[thick, domain=0:2, smooth, samples=100, variable=\x] plot ({\x},{0.6*\x*\x});
\draw[thick] (2,0) -- (2.8,0);
\node[below] at (2,0) {$2$};
\end{tikzpicture}
[/tikz]

